import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`online-course-gtm`,heroTitle:`Launch your online course in minutes`,heroSubtitle:`Perplexity Computer researches your market, writes your landing page, and builds your launch emails and ad copy — automatically.`,hasInputUrl:!1,heroOverlaySteps:[`Researching your course topic and target audience`,`Finding positioning angles and competitive gaps`,`Writing your landing page, launch emails, and ad copy`,`Complete go-to-market package assembled — ready to launch`],generatingSteps:[`Analyzing your course topic, audience, and competitive landscape`,`Designing an agent to craft positioning, landing page copy, and launch sequences`,`Configuring email sequences, ad variations, and webinar outlines`,`Setting up your complete course GTM package with all deliverables`],featureSectionTitle:`From course idea to launch-ready assets`,featureCardTitles:[`Connects to your course stack`,`Outputs you can publish`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Gmail, Google Docs, Notion, Canva, Google Sheets — Computer delivers your launch assets straight into the tools you already use to build and sell courses.`,`Landing page copy. 5-email launch sequence. Facebook and Instagram ad variations. Webinar outline with talking points. Positioning brief with competitive angles.`],capabilitySectionTitle:`Your launch team, on autopilot`,capabilitySectionSubtitle:`Describe your course, step away, come back to a complete go-to-market package.`,capabilityCards:[{title:`Market Research`,description:`Computer can analyze your course topic, identify competing offers, and surface the positioning angles that make your course stand out.`},{title:`Landing Page Copy`,description:`Computer can write a high-converting landing page — headline, subhead, benefit blocks, testimonials framework, and CTA — tailored to your audience.`},{title:`Launch Email Sequence`,description:`Computer can build a multi-email launch sequence — teaser, value, objection-handling, urgency, and last-chance emails — ready to load into your ESP.`},{title:`Connect Your Tools`,description:`Computer can push deliverables to Gmail, Google Docs, Notion, Google Sheets, and Canva — build workflows across your entire course launch stack.`},{title:`Remember & Refine`,description:`Computer can remember your brand voice, past launches, and audience insights — so every new campaign builds on what worked before.`},{title:`Monitor & Alert`,description:`Computer can track competitor course launches and market shifts — and flag new positioning opportunities or pricing changes you should respond to.`}]});export{t as default};
